css:
.loader {
  height: 60px;
  aspect-ratio: 1;
  border: 3px solid #524656;
  position: relative;
}
.loader:before,
.loader:after {
  content: "";
  position: absolute;
  width: 20%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: #CF4647;
  animation: 
    l8-0 .57s infinite alternate linear -.13s,
    l8-1 .35s infinite alternate linear -.23s;
}
.loader:after {
  background: #45ADA8;
  animation: 
    l8-0 .29s infinite alternate linear -.11s,
    l8-1 .51s infinite alternate linear -.34s;
}
@keyframes l8-0 {
  0%,5%  {bottom: 0%}
  95%,to {bottom: 80%}
}
@keyframes l8-1 {
  0%,5%  {left: 0%}
  95%,to {left: 80%}
}
